// BRANDS from run_scheduler.py. There is no 'grissomshop' folder in the repo even
// though the weekend brief lists it as a brand - unresolved, so it is excluded.
const today = new Date().toISOString().slice(0, 10);   // UTC, matches the Action
return ['ora', 'grissom', 'familybook'].map((brand) => ({
  json: { brand, today, file: `brands/${brand}/posts/${today}.md` },
}));

// Mirrors parse_today() in scripts/run_scheduler.py exactly.
const RAW = 'https://raw.githubusercontent.com/dkgrissom-tech/Ora-auto/main/';
const nowHour = new Date().getUTCHours();

// X is manual-only by policy in run_scheduler.py, so it is deliberately NOT
// enabled here. tiktok/youtube are video and belong to the video pipeline.
const POSTIZ_OK = ['bluesky', 'threads', 'instagram', 'pinterest', 'linkedin', 'mastodon'];
const POLICY_SKIP = { x: 'X is manual-only by policy', twitter: 'X is manual-only by policy',
                      tiktok: 'video - handled by the video pipeline',
                      youtube: 'video - handled by the video pipeline' };

// The HTTP node returns text, so it emits only { raw }. brand/file are recovered by
// index: one request per 'List Brands' item, in order.
const brandCtx = $('List Brands').all().map((b) => b.json);
const items = $input.all();
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const ctx = brandCtx[idx] || {};
  const brand = ctx.brand;
  const text = String(item.json.raw ?? item.json.data ?? '');
  if (!text || text.includes('"status": "404"') || text.startsWith('{"message"')) continue;

  const blocks = text.split('\n## ').slice(1);
  for (const b of blocks) {
    const nl = b.indexOf('\n');
    const header = (nl === -1 ? b : b.slice(0, nl)).trim();
    const bodySection = nl === -1 ? '' : b.slice(nl + 1);

    const hh = parseInt(header.split(':')[0], 10);
    if (Number.isNaN(hh)) continue;          // same as the Action's ValueError skip
    if (hh !== nowHour) continue;            // only this hour's blocks fire

    const meta = {};
    const bodyLines = [];
    let inBody = false, started = false;
    for (const line of bodySection.split('\n')) {
      if (line.trim() === '---') {
        if (!started) { started = true; inBody = true; continue; }
        break;
      }
      if (!inBody) {
        const i = line.indexOf(':');
        if (i > -1) meta[line.slice(0, i).trim().toLowerCase()] = line.slice(i + 1).trim();
      } else bodyLines.push(line);
    }

    const requested = String(meta.platforms || '')
      .split(',').map((p) => p.trim().toLowerCase()).filter(Boolean);
    const platforms = requested.filter((p) => POSTIZ_OK.includes(p));
    const skipped = requested.filter((p) => !POSTIZ_OK.includes(p))
      .map((p) => `${p}: ${POLICY_SKIP[p] || 'unsupported'}`);

    const media = meta.image || meta.video || '';
    out.push({ json: {
      brand: brand || 'unknown',
      file: ctx.file, header, hour: hh,
      platforms, policy_skipped: skipped,
      body: bodyLines.join('\n').trim(),
      media_path: media,
      media_url: media ? (media.startsWith('http') ? media : RAW + media) : '',
      pinterest_title: meta.pinterest_title || '',
      pinterest_url: meta.pinterest_url || '',
    }});
  }
}
return out;

for (const i of $input.all()) {
  const j = i.json;
  console.log(`[shortform-skip] ${j.brand} ${j.header}: platforms=${JSON.stringify(j.platforms)} `
    + `body=${(j.body || '').length}ch policy_skipped=${JSON.stringify(j.policy_skipped)}`);
}
return $input.all();

// Channel IDs resolved at runtime. 'Postiz: List Channels' runs once before the
// brand fan-out, so .first() is correct - it is one global list, not per-item data.
const d = $json;
const resp = $('Postiz: List Channels').first().json;
const list = Array.isArray(resp) ? resp
           : Array.isArray(resp.integrations) ? resp.integrations
           : Array.isArray(resp.data) ? resp.data : [];

let override = {};
try { override = JSON.parse($env.POSTIZ_CHANNEL_MAP || '{}'); } catch (e) {}

const brandWords = {
  ora: ['ora'],
  grissom: ['grissom', 'cedar hollow', 'dk grissom', 'd.k. grissom'],
  familybook: ['family', 'familybook', 'family book'],
};
const NEEDS_MEDIA = ['instagram', 'pinterest'];
const norm = (s) => String(s || '').toLowerCase();
const words = brandWords[d.brand] || [d.brand];
const hasMedia = Boolean(d.media_url);

const matched = [];
const problems = [...(d.policy_skipped || [])];
for (const platform of (d.platforms || [])) {
  if (NEEDS_MEDIA.includes(platform) && !hasMedia) {
    problems.push(`${platform}: needs an image, none in the block`);
    continue;
  }
  const ov = override?.[d.brand]?.[platform];
  if (ov) { matched.push({ platform, id: ov, name: '(override)' }); continue; }

  const hits = list.filter((c) => {
    const provider = norm(c.providerIdentifier || c.provider || c.identifier);
    if (provider !== platform) return false;
    if (c.disabled || c.refreshNeeded) return false;
    return words.some((w) => norm(c.name).includes(w));
  });
  if (hits.length === 1) matched.push({ platform, id: hits[0].id, name: hits[0].name });
  else if (hits.length > 1) problems.push(`${platform}: ${hits.length} channels match '${d.brand}' - set POSTIZ_CHANNEL_MAP`);
  else problems.push(`${platform}: no enabled Postiz channel matching brand '${d.brand}'`);
}

return { json: { ...d, channels: matched, channel_problems: problems,
                 has_channels: matched.length > 0,
                 needs_media: matched.some((c) => NEEDS_MEDIA.includes(c.platform)),
                 reason: problems.join('; ') } };

const d = $('Match Brand Channels').item.json;
const up = $json || {};
const id = up.id ?? up._id ?? null;
const path = up.path ?? up.url ?? null;
if (!id || !path) {
  return { json: { ...d, media: [], media_failed: true,
                   reason: `Postiz upload failed for ${d.media_url}` } };
}
return { json: { ...d, media: [{ id, path }], media_failed: false } };

const d = $json;
if (d.media_failed && d.needs_media) return { json: { ...d, skip_publish: true } };

// Per-network ceilings so one long block is not rejected by the strictest network.
const LIMIT = { bluesky: 300, threads: 500, pinterest: 500, instagram: 2200,
                linkedin: 3000, mastodon: 500 };
const clip = (s, n) => (s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '\u2026');

const settingsFor = (platform) => {
  if (platform === 'pinterest') {
    // post_pinterest() in run_scheduler.py falls back to the bare brand name for the
    // title and to '' for the link. 61 of the 66 Aug 4-18 pins carry neither meta key,
    // so that fallback would ship pins titled 'grissom' with no destination. Derive
    // instead: first bold/heading line of the body, then a per-brand default link.
    const firstLine = String(d.body || '').split('\n')
      .map((l) => l.replace(/<!--.*?-->/g, '').trim())
      .find((l) => l && !l.startsWith('#'));
    const derived = String(firstLine || '')
      .replace(/^#+\s*/, '').replace(/\*\*/g, '').replace(/[*_`]/g, '')
      .replace(/["\u201c\u201d]/g, '')
      .replace(/\s*\|\s*/g, ' - ').replace(/\s{2,}/g, ' ').trim();
    const s = { __type: 'pinterest',
                title: clip(d.pinterest_title || derived || d.brand, 100) };
    const link = d.pinterest_url
      || $env[`${String(d.brand).toUpperCase()}_PINTEREST_LINK`]
      || $env.POSTIZ_DEFAULT_LINK;
    if (link) s.link = link;
    const board = $env[`${String(d.brand).toUpperCase()}_PINTEREST_BOARD`] || $env.POSTIZ_PINTEREST_BOARD;
    if (board) s.board = board;
    return s;
  }
  if (platform === 'instagram') return { __type: 'instagram', post_type: 'post' };
  if (platform === 'linkedin') return { __type: 'linkedin' };
  return { __type: platform };
};

const payload = {
  type: 'now', date: new Date().toISOString(), shortLink: false, tags: [],
  posts: d.channels.map((c) => ({
    integration: { id: c.id },
    value: [{ content: clip(d.body, LIMIT[c.platform] || 500), image: d.media }],
    settings: settingsFor(c.platform),
  })),
};
return { json: { ...d, skip_publish: false, postiz_payload: payload } };

// Nothing is renamed or deleted: brands/<brand>/posts/<date>.md holds many blocks
// and the hour match is what prevents repeats - same contract as auto_post.yml.
for (const i of $input.all()) {
  const d = $('Build Postiz Payload').item.json;
  console.log(`[shortform-posted] ${d.brand} ${d.header} -> `
    + d.channels.map((c) => `${c.platform}(${c.name})`).join(', '));
}
return $input.all();
